CREATE FUNCTION public.release_group_campaign(cid uuid,final_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.group_buying_campaigns; BEGIN SELECT * INTO c FROM public.group_buying_campaigns WHERE id=cid FOR UPDATE; IF c.lifecycle NOT IN ('active','draft') THEN RETURN; END IF; IF c.committed_quantity>0 THEN UPDATE public.products SET stock=stock+c.committed_quantity WHERE id=c.product_id; END IF; UPDATE public.group_buying_participants SET commitment_status='released' WHERE campaign_id=cid AND commitment_status='committed'; UPDATE public.group_buying_campaigns SET lifecycle=final_state WHERE id=cid; END $$;
REVOKE ALL ON FUNCTION public.release_group_campaign(uuid,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.expire_group_campaigns() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; BEGIN FOR c IN SELECT id FROM public.group_buying_campaigns WHERE lifecycle='active' AND closes_at<=now() ORDER BY id FOR UPDATE SKIP LOCKED LOOP PERFORM public.release_group_campaign(c.id,'expired'); END LOOP; UPDATE public.group_buying_campaigns c SET lifecycle='completed' WHERE c.lifecycle='target_reached' AND c.closes_at<=now() AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.campaign_id=c.id AND o.status NOT IN ('delivered','completed','rejected','cancelled')); END $$;
REVOKE ALL ON FUNCTION public.expire_group_campaigns() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.expire_group_campaigns() TO anon,authenticated;
CREATE FUNCTION public.create_group_campaign(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.products; cid uuid; target integer; maximum integer; price numeric; starts timestamptz; deadline timestamptz; state text; BEGIN
SELECT * INTO p FROM public.products WHERE id=(payload->>'productId')::uuid FOR UPDATE;
IF auth.uid() IS NULL OR NOT public.owns_supplier(p.supplier_id) OR NOT public.public_product(p.id) OR NOT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=p.supplier_id AND verification_status='approved') THEN RAISE EXCEPTION 'Approved supplier and eligible owned product required'; END IF;
target:=(payload->>'target')::integer;maximum:=(payload->>'maximum')::integer;price:=(payload->>'groupPrice')::numeric;starts:=(payload->>'startsAt')::timestamptz;deadline:=(payload->>'deadline')::timestamptz;state:=payload->>'state';
IF target IS NULL OR maximum IS NULL OR price IS NULL OR starts IS NULL OR deadline IS NULL OR state IS NULL OR state NOT IN ('draft','active') OR target<1 OR maximum<target OR maximum>p.stock OR maximum>1000000 OR price<=0 OR price>=p.price OR round(price,2)<>price OR deadline<=starts OR deadline<=now() OR length(trim(COALESCE(payload->>'title','')))=0 OR length(payload->>'title')>150 THEN RAISE EXCEPTION 'Invalid campaign'; END IF;
INSERT INTO public.group_buying_campaigns(supplier_id,product_id,title,target_quantity,unit_price,closes_at,lifecycle,normal_price,max_quantity,starts_at) VALUES(p.supplier_id,p.id,payload->>'title',target,price,deadline,state,p.price,maximum,starts) RETURNING id INTO cid;RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.create_group_campaign(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_group_campaign(jsonb) TO authenticated;
CREATE FUNCTION public.manage_group_campaign(cid uuid,action text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.group_buying_campaigns; BEGIN SELECT * INTO c FROM public.group_buying_campaigns WHERE id=cid FOR UPDATE; IF auth.uid() IS NULL OR c.id IS NULL OR NOT public.owns_supplier(c.supplier_id) OR NOT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=c.supplier_id AND verification_status='approved') THEN RAISE EXCEPTION 'Supplier access required'; END IF;
IF action='activate' AND c.lifecycle='draft' AND c.closes_at>now() AND public.public_product(c.product_id) THEN UPDATE public.group_buying_campaigns SET lifecycle='active' WHERE id=cid; RETURN 'active'; END IF;
IF action='cancel' AND c.lifecycle IN ('draft','active') THEN PERFORM public.release_group_campaign(cid,'cancelled'); RETURN 'cancelled'; END IF; RAISE EXCEPTION 'Invalid campaign transition'; END $$;
REVOKE ALL ON FUNCTION public.manage_group_campaign(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_group_campaign(uuid,text) TO authenticated;
CREATE FUNCTION public.join_group_campaign(cid uuid,qty integer,address jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.group_buying_campaigns; p public.products; g record; oid uuid; BEGIN
IF NOT public.group_buyer_eligible() THEN RAISE EXCEPTION 'Confirmed buyer account required'; END IF;
SELECT * INTO c FROM public.group_buying_campaigns WHERE id=cid FOR UPDATE;
IF c.id IS NULL THEN RAISE EXCEPTION 'Campaign not found'; END IF;
IF EXISTS(SELECT 1 FROM public.group_buying_participants WHERE campaign_id=cid AND user_id=auth.uid()) THEN RETURN c.lifecycle; END IF;
IF c.lifecycle='active' AND c.closes_at<=now() THEN PERFORM public.release_group_campaign(cid,'expired');RETURN 'expired';END IF;
IF c.lifecycle NOT IN ('active','target_reached') OR c.starts_at>now() OR c.closes_at<=now() THEN RAISE EXCEPTION 'Campaign is not accepting commitments'; END IF;
SELECT * INTO p FROM public.products WHERE id=c.product_id FOR UPDATE;
IF NOT public.public_product(p.id) OR qty IS NULL OR qty<1 OR qty>1000000 OR qty>p.stock OR c.committed_quantity+qty>c.max_quantity THEN RAISE EXCEPTION 'Invalid quantity or campaign capacity exceeded'; END IF;
IF address IS NULL OR jsonb_typeof(address)<>'object' OR length(trim(COALESCE(address->>'name','')))<1 OR length(address->>'name')>100 OR length(COALESCE(address->>'phone','')) NOT BETWEEN 5 AND 30 OR length(trim(COALESCE(address->>'city','')))<1 OR length(address->>'city')>100 OR length(trim(COALESCE(address->>'address','')))<5 OR length(address->>'address')>500 OR length(COALESCE(address->>'notes',''))>1000 THEN RAISE EXCEPTION 'Delivery information required'; END IF;
INSERT INTO public.group_buying_participants(campaign_id,user_id,quantity,delivery) VALUES(cid,auth.uid(),qty,address);
UPDATE public.products SET stock=stock-qty WHERE id=p.id;
UPDATE public.group_buying_campaigns SET committed_quantity=committed_quantity+qty,business_count=business_count+1 WHERE id=cid RETURNING * INTO c;
IF c.committed_quantity>=c.target_quantity THEN
FOR g IN SELECT * FROM public.group_buying_participants WHERE campaign_id=cid AND commitment_status='committed' ORDER BY id LOOP
INSERT INTO public.orders(buyer_id,supplier_id,status,total,delivery,request_key,campaign_id) VALUES(g.user_id,c.supplier_id,'pending',g.quantity*c.unit_price,g.delivery,cid,cid) RETURNING id INTO oid;
INSERT INTO public.order_items(order_id,product_id,quantity,unit_price,name_en,name_ar,price_unit,pack_size) VALUES(oid,p.id,g.quantity,c.unit_price,p.name_en,p.name_ar,p.price_unit,p.pack_size);
UPDATE public.group_buying_participants SET order_id=oid,commitment_status='ordered' WHERE id=g.id;END LOOP;
UPDATE public.group_buying_campaigns SET lifecycle='target_reached' WHERE id=cid;RETURN 'target_reached';END IF;RETURN 'active'; END $$;
REVOKE ALL ON FUNCTION public.join_group_campaign(uuid,integer,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_group_campaign(uuid,integer,jsonb) TO authenticated;
CREATE FUNCTION public.sync_group_completion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.campaign_id IS NOT NULL AND NEW.status IN ('delivered','completed','rejected','cancelled') THEN UPDATE public.group_buying_campaigns c SET lifecycle='completed' WHERE c.id=NEW.campaign_id AND c.lifecycle='target_reached' AND (c.closes_at<=now() OR c.committed_quantity=c.max_quantity) AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.campaign_id=c.id AND o.status NOT IN ('delivered','completed','rejected','cancelled')); END IF;RETURN NEW;END $$;
CREATE TRIGGER sync_group_order_completion AFTER UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.sync_group_completion();